+// API keys, roles and the audit log. A viewer may only read; a cook may also
+// cook, record waste, log temperatures and enter stock-take counts; a manager
+// may do everything. Requests that change data are written to the audit log.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** The roles, least to most allowed. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+// Routes ("METHOD /pattern") a cook may use besides reading.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reads only managers may make.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for `key`, or null (compares in constant time). */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (timingSafeEqual(digest(k.key), wanted) && !found) found = k;
+  }
+  return found && ROLES.includes(found.role) ? found : null;
+}
+
+/** Whether `role` may use `route` ("METHOD /pattern"). */
+export function allowed(role, route) {
+  if (role === "manager") return true;
+  if (MANAGER_READS.has(route)) return false;
+  if (route.startsWith("GET ")) return role === "viewer" || role === "cook";
+  return role === "cook" && COOK_ROUTES.has(route);
+}
+
+/** Appends an audit entry { id, at, keyName, method, path, status }; returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
