+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+import { migrate } from "../src/db/migrations.js";
+
+test("requests without a key or with an unknown key are 401", async () => {
+  const { handle, store } = app();
+  const none = await handle({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(bad.status, 401);
+  const before = JSON.stringify(store.data.batches);
+  const post = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(post.status, 401);
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/nope" })).status, 401);
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app();
+  assert.equal((await handle({ path: "/items", headers: auth("viewer") })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("viewer"), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, nothing else", async () => {
+  const { handle } = app();
+  const h = auth("cook");
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: h, body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: h, body: { qty: 0.5 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: h, body: { location: "fridge", celsius: 3 } })).status, 201);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: auth(), body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: h, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: h })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: h, body: { location: "fridge" } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", headers: h, body: {} })).status, 403);
+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", headers: h, body: { allergens: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: h })).status, 403);
+});
+
+test("changes are audited and GET /audit lists them newest first for managers", async () => {
+  const { handle, store } = app();
+  await handle({ path: "/items", headers: auth("cook") });
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("cook"), body: { portions: 1 } });
+  await handle({ method: "POST", path: "/orders/1/send", headers: auth("viewer") });
+  await handle({ method: "POST", path: "/orders/1/send", body: {} });
+  assert.equal(store.data.audit.length, 2);
+  const res = await handle({ path: "/audit", headers: auth("manager") });
+  assert.equal(res.status, 200);
+  assert.deepEqual(
+    res.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })),
+    [
+      { keyName: "front of house", method: "POST", path: "/orders/1/send", status: 403 },
+      { keyName: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+    ],
+  );
+  assert.match(res.body[0].at, /^2026-10-28T10:00:00/);
+  assert.equal((await handle({ path: "/audit", headers: auth("viewer") })).status, 403);
+  assert.ok(!JSON.stringify(res.body).includes("seed-"));
+});
+
+test("schema 2 files open with no keys and an empty audit log", () => {
